import json
import re
from pathlib import Path
from typing import Dict, List, Tuple, Optional

SECTION_RE = re.compile(r"^\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^(\d+)\.\s*(.*)$")


def _parse_entry(line: str) -> Tuple[str, str, str, Optional[str]]:
    """
    Returns (entry_type, speaker, text, target)
    entry_type: "line" or "choice"
    """
    target = None
    if "->" in line:
        left, right = line.split("->", 1)
        target = right.strip()
    else:
        left = line

    left = left.strip()
    m_choice = CHOICE_RE.match(left)
    if m_choice:
        text = m_choice.group(2).strip()
        return "choice", "", text, target

    if ":" in left:
        speaker, text = left.split(":", 1)
        return "line", speaker.strip(), text.strip(), target

    # Fallback: treat as line with no speaker
    return "line", "", left, target


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id: Optional[str] = None
    current_lines: List[str] = []

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        m = SECTION_RE.match(line)
        if m:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = m.group(1).strip()
            current_lines = []
        else:
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    for section_id, lines in sections:
        parsed = [_parse_entry(l) for l in lines]
        has_choices = any(t == "choice" for t, _, _, _ in parsed)
        node_type = "choice" if has_choices else "line"

        speaker = ""
        text_accum = ""
        if node_type == "line":
            line_entries = [p for p in parsed if p[0] == "line"]
            speakers = [p[1] for p in line_entries if p[1]]
            if speakers and all(s == speakers[0] for s in speakers):
                speaker = speakers[0]
            texts = [p[2] for p in line_entries]
            text_accum = "\n".join(t for t in texts if t).strip()

        nodes.append({
            "id": section_id,
            "text": text_accum,
            "speaker": speaker,
            "type": node_type,
        })

        for entry_type, _speaker, entry_text, target in parsed:
            if not target:
                continue
            edges.append({
                "from": section_id,
                "to": target,
                "text": entry_text,
            })

    # Ensure End node exists if referenced
    node_ids = {n["id"] for n in nodes}
    if any(e["to"] == "End" for e in edges) and "End" not in node_ids:
        nodes.append({
            "id": "End",
            "text": "",
            "speaker": "",
            "type": "line",
        })

    graph = {"nodes": nodes, "edges": edges}
    _validate_graph(graph)
    return graph


def _validate_graph(graph: Dict[str, List[Dict[str, str]]]) -> None:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])
    if not nodes:
        raise ValueError("Graph has no nodes")

    node_ids = {n["id"] for n in nodes}

    missing = [e for e in edges if e["to"] not in node_ids]
    if missing:
        missing_ids = ", ".join(sorted({e["to"] for e in missing}))
        raise ValueError(f"Missing target nodes: {missing_ids}")

    # Reachability from first node
    start = nodes[0]["id"]
    adjacency: Dict[str, List[str]] = {}
    for e in edges:
        adjacency.setdefault(e["from"], []).append(e["to"])

    visited = set()
    stack = [start]
    while stack:
        nid = stack.pop()
        if nid in visited:
            continue
        visited.add(nid)
        for nxt in adjacency.get(nid, []):
            if nxt not in visited:
                stack.append(nxt)

    unreachable = [n for n in nodes if n["id"] not in visited]
    if unreachable:
        unreachable_ids = ", ".join(n["id"] for n in unreachable)
        raise ValueError(f"Unreachable nodes: {unreachable_ids}")


def _escape_dot(text: str) -> str:
    return (
        text.replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\n", "\\n")
    )


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {"]
    for n in graph["nodes"]:
        label_parts = [n["id"]]
        if n.get("speaker"):
            label_parts.append(n["speaker"])
        if n.get("text"):
            label_parts.append(n["text"])
        label = _escape_dot("\\n".join(label_parts))
        shape = "diamond" if n.get("type") == "choice" else "box"
        lines.append(f"  \"{_escape_dot(n['id'])}\" [label=\"{label}\", shape={shape}];")
    for e in graph["edges"]:
        elabel = _escape_dot(e.get("text", ""))
        lines.append(
            f"  \"{_escape_dot(e['from'])}\" -> \"{_escape_dot(e['to'])}\" [label=\"{elabel}\"];"
        )
    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    script_path = Path("/app/script.txt")
    out_json = Path("/app/dialogue.json")
    out_dot = Path("/app/dialogue.dot")

    text = script_path.read_text(encoding="utf-8")
    graph = parse_script(text)

    out_json.write_text(json.dumps(graph, indent=2), encoding="utf-8")
    out_dot.write_text(graph_to_dot(graph), encoding="utf-8")


if __name__ == "__main__":
    main()
